export interface ConnectorConfig {
  /** Slack bot token with chat:write scope */
  slackBotToken: string
  /** Twilio auth token for validating X-Twilio-Signature header */
  twilioAuthToken: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface TwilioSmsPayload {
  MessageSid: string
  AccountSid: string
  From: string
  To: string
  Body?: string
  NumMedia: string
  NumSegments: string
  [key: string]: string | undefined
}

export interface HandleResult {
  slackMessageId: string
  channel: string
}

const SALES_KEYWORDS = /pricing|quote|demo/i

function validateTwilioSignature(
  payload: string,
  signature: string | null,
  authToken: string,
  url: string
): boolean {
  if (!signature) return false
  const crypto = globalThis.crypto ?? require('crypto')
  const expectedSignature = crypto
    .createHmac('sha1', authToken)
    .update(url + payload)
    .digest('base64')
  return signature === expectedSignature
}

export async function handle(
  payload: TwilioSmsPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const { slackBotToken, twilioAuthToken, fetch = globalThis.fetch } = config

  if (!payload.Body && payload.Body !== '') {
    throw new Error('Missing required field: Body')
  }
  if (!payload.From) {
    throw new Error('Missing required field: From')
  }

  const bodyText = payload.Body ?? ''
  const channel = SALES_KEYWORDS.test(bodyText) ? '#sales' : '#support'

  const requestBody = JSON.stringify({
    channel,
    text: bodyText,
  })

  const response = await fetch('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: requestBody,
  })

  if (!response.ok) {
    throw new Error(
      `Slack API error: ${response.status} ${response.statusText} at POST https://slack.com/api/chat.postMessage`
    )
  }

  const result = (await response.json()) as { ok: boolean; channel: string; ts: string }

  return {
    slackMessageId: result.ts,
    channel: result.channel,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, TwilioSmsPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      twilioAuthToken: 'test-auth-token',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TwilioSmsPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.channel).toBe('C01JASD6802')
    expect(result.slackMessageId).toBe('1234567890.123456')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.url === 'https://slack.com/api/chat.postMessage' && req.method === 'POST') {
        return jsonResponse({ ok: true, channel: 'C01JASD6802', ts: '1234567890.123456' })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    calls = recordedCalls
    baseConfig = {
      slackBotToken: 'xoxb-test-token',
      twilioAuthToken: 'test-auth-token',
      fetch,
    }
  })

  it('routes pricing inquiry to #sales channel', async () => {
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'I need pricing for your enterprise plan',
    }
    const result = await handle(payload, baseConfig)
    expect(result.channel).toBe('C01JASD6802')
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'I need pricing for your enterprise plan' })
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-test-token')
  })

  it('routes quote request to #sales channel', async () => {
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Please send me a quote',
    }
    const result = await handle(payload, baseConfig)
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'Please send me a quote' })
  })

  it('routes demo request to #sales channel (case insensitive)', async () => {
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Can I schedule a DEMO?',
    }
    const result = await handle(payload, baseConfig)
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'Can I schedule a DEMO?' })
  })

  it('routes general inquiry to #support channel', async () => {
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'How do I reset my password?',
    }
    const result = await handle(payload, baseConfig)
    expect(calls[0].json).toEqual({ channel: '#support', text: 'How do I reset my password?' })
  })

  it('routes empty body to #support channel', async () => {
    const payload: TwilioSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: '',
    }
    const result = await handle(payload, baseConfig)
    expect(calls[0].json).toEqual({ channel: '#support', text: '' })
  })

  it('throws when Body field is missing', async () => {
    const payload = { ...SOURCE_EXAMPLE }
    delete (payload as Record<string, unknown>).Body
    await expect(handle(payload as unknown as TwilioSmsPayload, baseConfig)).rejects.toThrow(
      'Missing required field: Body'
    )
  })

  it('throws when From field is missing', async () => {
    const payload = { ...SOURCE_EXAMPLE }
    delete (payload as Record<string, unknown>).From
    await expect(handle(payload as unknown as TwilioSmsPayload, baseConfig)).rejects.toThrow(
      'Missing required field: From'
    )
  })

  it('throws on non-2xx Slack response with status and endpoint', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'invalid_auth' }, 401))
    const config = { ...baseConfig, fetch }
    const payload: TwilioSmsPayload = { ...SOURCE_EXAMPLE, Body: 'test' }
    await expect(handle(payload, config)).rejects.toThrow(
      'Slack API error: 401 Unauthorized at POST https://slack.com/api/chat.postMessage'
    )
    expect(errorCalls[0].json).toEqual({ channel: '#support', text: 'test' })
  })

  it('uses injected fetch from config', async () => {
    const { fetch, calls: injectedCalls } = fakeFetch(() =>
      jsonResponse({ ok: true, channel: 'C123', ts: '999' })
    )
    const config = { ...baseConfig, fetch }
    const payload: TwilioSmsPayload = { ...SOURCE_EXAMPLE, Body: 'test' }
    const result = await handle(payload, config)
    expect(injectedCalls.length).toBe(1)
    expect(result.slackMessageId).toBe('999')
  })
})

